async save(
  state: EditorState,
  options: {
    memoName?: string;
    parentMemoName?: string;
  },
): Promise<{ memoName: string; hasChanges: boolean }> {
  // 1. Upload local files first
  const newAttachments = await uploadService.uploadFiles(state.localFiles);
  const allAttachments = [...state.metadata.attachments, ...newAttachments];

  // 2. Update existing memo
  if (options.memoName) {
    const prevMemo = await memoServiceClient.getMemo({ name: options.memoName });
    const { mask, patch } = buildUpdateMask(prevMemo, state, allAttachments);

    if (mask.size === 0) {
      return { memoName: prevMemo.name, hasChanges: false };
    }

    const memo = await memoServiceClient.updateMemo({
      memo: create(MemoSchema, patch as Record<string, unknown>),
      updateMask: create(FieldMaskSchema, { paths: Array.from(mask) }),
    });
    return { memoName: memo.name, hasChanges: true };
  }

  // 3. Create new memo or comment
  const memoData = create(MemoSchema, {
    content: state.content,
    visibility: state.metadata.visibility,
    attachments: toAttachmentReferences(allAttachments),
    relations: state.metadata.relations,
    location: state.metadata.location,
    createTime: state.timestamps.createTime ? timestampFromDate(state.timestamps.createTime) : undefined,
    updateTime: state.timestamps.updateTime ? timestampFromDate(state.timestamps.updateTime) : undefined,
  });

  const memo = options.parentMemoName
    ? await memoServiceClient.createMemoComment({
        name: options.parentMemoName,
        comment: memoData,
      })
    : await memoServiceClient.createMemo({ memo: memoData });

  return { memoName: memo.name, hasChanges: true };
},

const handleReactionClick = async (reactionType: string) => {
  if (!currentUser) return;

  try {
    if (hasReacted(reactionType)) {
      const reactions = memo.reactions.filter(
        (reaction) => reaction.reactionType === reactionType && reaction.creator === currentUser.name,
      );
      await Promise.all(reactions.map((reaction) => memoServiceClient.deleteMemoReaction({ name: reaction.name })));
    } else {
      await memoServiceClient.upsertMemoReaction({
        name: memo.name,
        reaction: { contentId: memo.name, reactionType },
      });
    }
    // Refetch the memo to get updated reactions and invalidate cache
    const updatedMemo = await memoServiceClient.getMemo({ name: memo.name });
    queryClient.setQueryData(memoKeys.detail(memo.name), updatedMemo);
    queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
    // If this memo is a comment, refresh the parent's comments list so the comment's reactions update in the UI
    if (memo.parent) {
      queryClient.invalidateQueries({ queryKey: memoKeys.comments(memo.parent) });
    }
  } catch {
    // skip error
  }
  onComplete?.();
};

const listAccessTokens = async (parent: string) => {
  const { personalAccessTokens } = await userServiceClient.listPersonalAccessTokens({ parent });
  return personalAccessTokens.sort(
    (a, b) =>
      ((b.createdAt ? timestampDate(b.createdAt) : undefined)?.getTime() ?? 0) -
      ((a.createdAt ? timestampDate(a.createdAt) : undefined)?.getTime() ?? 0),
  );
};

const fetchData = async () => {
  if (!currentUser?.name) {
    return;
  }
  const [{ identityProviders }, { linkedIdentities }] = await Promise.all([
    identityProviderServiceClient.listIdentityProviders({}),
    userServiceClient.listLinkedIdentities({ parent: currentUser.name }),
  ]);
  setIdentityProviderList(identityProviders);
  setLinkedIdentityList(linkedIdentities);
};

export function useInstanceSetting(key: InstanceSetting_Key) {
  return useQuery({
    queryKey: instanceKeys.setting(key),
    queryFn: async () => {
      const setting = await instanceServiceClient.getInstanceSetting({
        name: buildInstanceSettingName(key),
      });
      return setting;
    },
    staleTime: 1000 * 60 * 5, // 5 minutes
  });
}

export function useInfiniteMemos(request: Partial<ListMemosRequest> = {}, options?: { enabled?: boolean }) {
  return useInfiniteQuery({
    queryKey: memoKeys.list(request),
    queryFn: async ({ pageParam }) => {
      const response = await memoServiceClient.listMemos(
        create(ListMemosRequestSchema, {
          ...request,
          pageToken: pageParam || "",
        } as Record<string, unknown>),
      );
      return response;
    },
    initialPageParam: "",
    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
    staleTime: 1000 * 60,
    gcTime: 1000 * 60 * 5,
    enabled: options?.enabled ?? true,
  });
}

export function useNotifications() {
  const currentUser = useCurrentUser();

  return useQuery({
    queryKey: userKeys.notifications(),
    queryFn: async () => {
      if (!currentUser?.name) {
        return [];
      }
      const { notifications } = await userServiceClient.listUserNotifications({ parent: currentUser.name });
      return notifications;
    },
    enabled: !!currentUser?.name,
    staleTime: 1000 * 30, // 30 seconds - notifications should update frequently
  });
}

export function useTagCounts(forCurrentUser = false) {
  const currentUser = useCurrentUser();

  return useQuery<UserStats | Record<string, number>, Error, Record<string, number>>({
    queryKey:
      forCurrentUser && currentUser?.name
        ? userKeys.userStats(currentUser.name)
        : [...userKeys.stats(), "tagCounts", forCurrentUser ? "current" : "all"],
    queryFn: async (): Promise<UserStats | Record<string, number>> => {
      if (forCurrentUser) {
        if (!currentUser?.name) {
          return {};
        }
        return userServiceClient.getUserStats({ name: currentUser.name });
      } else {
        // Fetch all user stats
        const { stats } = await userServiceClient.listAllUserStats({});

        // Aggregate tag counts from all users
        const tagCount: Record<string, number> = {};
        for (const userStats of stats) {
          if (userStats.tagCount) {
            for (const [tag, count] of Object.entries(userStats.tagCount)) {
              tagCount[tag] = (tagCount[tag] || 0) + count;
            }
          }
        }
        return tagCount;
      }
    },
    select: (data) => {
      if (forCurrentUser) {
        return (data as UserStats).tagCount || {};
      }
      return data as Record<string, number>;
    },
    enabled: !forCurrentUser || !!currentUser?.name,
    staleTime: 1000 * 60 * 2, // 2 minutes - tags don't change frequently
  });
}

export function useUpdateUser() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ user, updateMask }: { user: Partial<User>; updateMask: string[] }) => {
      const updatedUser = await userServiceClient.updateUser({
        user: user as User,
        updateMask: create(FieldMaskSchema, { paths: updateMask }),
      });
      return updatedUser;
    },
    onSuccess: (updatedUser) => {
      queryClient.setQueryData(userKeys.detail(updatedUser.name), updatedUser);
      queryClient.invalidateQueries({ queryKey: userKeys.currentUser() });
    },
  });
}

export function useUsersByNames(names: string[]) {
  const enabled = names.length > 0;
  const uniqueNames = Array.from(new Set(names));

  return useQuery({
    queryKey: userKeys.byNames(uniqueNames),
    queryFn: async () => {
      const users = await Promise.all(
        uniqueNames.map(async (name) => {
          try {
            const user = await userServiceClient.getUser({ name });
            return { name, user };
          } catch {
            return { name, user: undefined };
          }
        }),
      );

      const userMap = new Map<string, User | undefined>();
      for (const { name, user } of users) {
        userMap.set(name, user);
      }
      return userMap;
    },
    enabled,
    staleTime: 1000 * 60 * 5, // 5 minutes - user profiles don't change often
  });
}

